const crypto = require('crypto');

const request = $json;
const headers = request.headers || {};
const body = request.body || {};
const eventId = String(headers['x-scriptflow-event-id'] || '');
const timestamp = String(headers['x-scriptflow-timestamp'] || '');
const suppliedSignature = String(headers['x-scriptflow-signature'] || '').toLowerCase();
const secret = $env.N8N_SCRIPTFLOW_WEBHOOK_SECRET;
const now = Date.now();
const timestampMilliseconds = Number(timestamp) * 1000;

if (!secret || !eventId || !Number.isFinite(timestampMilliseconds) || Math.abs(now - timestampMilliseconds) > 300000) {
  throw new Error('Rejected Scriptflow event: missing secret, event id, or fresh timestamp.');
}

const payload = JSON.stringify(body);
const expectedSignature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + payload).digest('hex');
const suppliedBuffer = Buffer.from(suppliedSignature);
const expectedBuffer = Buffer.from(expectedSignature);

if (suppliedBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(suppliedBuffer, expectedBuffer)) {
  throw new Error('Rejected Scriptflow event: invalid HMAC signature.');
}

return [{ json: { ...body, verifiedBy: 'n8n-hmac', receivedAt: new Date().toISOString() } }];
